package sigepac.poo.infraestructura.persistencia;
import sigepac.poo.dominio.repositorios.IRepositorioNegocioComercial;import sigepac.poo.dominio.entidades.NegocioComercial;import sigepac.poo.infraestructura.ConexionPoo;import java.sql.*;import java.util.*;
/** Adaptador JDBC de negocios. */
public class RepositorioNegocioComercialJdbc implements IRepositorioNegocioComercial {
 private NegocioComercial map(ResultSet r)throws SQLException{return new NegocioComercial(r.getInt("id_negocio"),r.getInt("id_propietario"),r.getString("nombre_comercial"),r.getString("numero_local"),r.getBoolean("esta_activo"),r.getString("propietario"));}
 private static final String SEL="SELECT n.*,CONCAT(c.nombre,' ',c.apellido) propietario FROM oop_negocios_comerciales n JOIN oop_cuentas_usuario c ON c.id_cuenta=n.id_propietario";
 public NegocioComercial buscarPorId(int id){try(Connection c=ConexionPoo.abrir();PreparedStatement p=c.prepareStatement(SEL+" WHERE n.id_negocio=?")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){return r.next()?map(r):null;}}catch(SQLException e){throw ConexionPoo.fallo(e);}}
 public boolean existe(int id){try(Connection c=ConexionPoo.abrir();PreparedStatement p=c.prepareStatement("SELECT 1 FROM oop_negocios_comerciales WHERE id_negocio=? AND esta_activo=1")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){return r.next();}}catch(SQLException e){throw ConexionPoo.fallo(e);}}
 public List<NegocioComercial> obtenerTodos(){List<NegocioComercial>a=new ArrayList<>();try(Connection c=ConexionPoo.abrir();Statement s=c.createStatement();ResultSet r=s.executeQuery(SEL+" ORDER BY n.id_negocio")){while(r.next())a.add(map(r));return a;}catch(SQLException e){throw ConexionPoo.fallo(e);}}
 public int guardar(NegocioComercial n){try(Connection c=ConexionPoo.abrir();PreparedStatement p=c.prepareStatement("INSERT INTO oop_negocios_comerciales(id_propietario,nombre_comercial,numero_local,esta_activo) VALUES(?,?,?,?)",Statement.RETURN_GENERATED_KEYS)){p.setInt(1,n.getIdPropietario());p.setString(2,n.getNombreComercial());p.setString(3,n.getNumeroLocal());p.setBoolean(4,n.isEstaActivo());p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){if(r.next())return r.getInt(1);throw new SQLException("Falta id generado");}}catch(SQLException e){throw ConexionPoo.fallo(e);}}
 public boolean eliminar(int id){try(Connection c=ConexionPoo.abrir();PreparedStatement p=c.prepareStatement("UPDATE oop_negocios_comerciales SET esta_activo=0 WHERE id_negocio=?")){p.setInt(1,id);return p.executeUpdate()>0;}catch(SQLException e){throw ConexionPoo.fallo(e);}}
}
